void news_tts_notify_play_complete(uint32_t event,void *userdata)
{
    ps_data_msg_send_music_pending_restore(1);
}

int32_t news_ring_notify_play_complete(void *p_param, uint32_t size)
{
    app_event_audio_t  *p_app_event;

    p_app_event = p_param;
    if(p_app_event->event_id!=APP_EVENT_AUDIO_PLAY_BUF_START)
    {
        ps_data_msg_send_call_ring_stop();
        ps_data_msg_send_music_pending_restore(1);
    }

    return 0;
}

void ui_ScreenRemindNews_screen_loard(lv_obj_t * ui_ScreenRemindNews)
{
    ui_screen_remind_news_obj_t * p_screen_param;

    p_screen_param      = (ui_screen_remind_news_obj_t *) lv_obj_get_user_data(ui_ScreenRemindNews);

    uint32_t        ret;

    if (p_screen_param->enter_param.type == news_type_sms) {
        if(get_app_fp_play_tts_news_is_enable()){
            ps_data_msg_send_music_pending_restore(0);
            app_tts_set_notify_fun(news_tts_notify_play_complete,NULL);
            ret = app_fp_play_tts_news(lv_label_get_text(p_screen_param->obj_label_remind));
        }else{
            if(get_incoming_call_volume() == 0x80)	// 静音模式
            {

            }
            else
            {			
                ps_data_msg_send_music_pending_restore(0);
                settings_fp_flow_set_master_volume(get_incoming_call_volume(),get_incoming_sms_ring(),0,news_ring_notify_play_complete);
            }
        }
    }

    backlight_turn_on();
}


void remind_news_key_event(uint32_t key,lv_obj_t * ui_Screen)
{
    ui_screen_remind_news_obj_t * p_screen_param;

    p_screen_param      = (ui_screen_remind_news_obj_t *) lv_obj_get_user_data(ui_Screen);

    //__inf("sms_menu_key_event key:%d,child_id:%d,child_cnt:%d\r\n",key,child_id,child_cnt);
    if (p_screen_param->enter_param.type == news_type_sms) {
        remind_fp_reset_sms_count();

        }
    else if (p_screen_param->enter_param.type == news_type_call) {
        remind_fp_reset_call_count();

        }

    switch (key)
    {
        case LV_KEY_UP:
            {

                }
            break;

        case LV_KEY_DOWN:
            {

                }
            break;

        case APP_KEY_VALUE_TOP_LEFT:
            {
                if (p_screen_param->enter_param.type == news_type_sms) {
                    void *          p_enter_param;

                    p_enter_param       = (void *) create_app_sms_enter_param_fisrt_rev_win();
                    alv_am_app_exit_action(NULL,"sms",NULL);
                    alv_am_app_enter_action(NULL,"sms",p_enter_param);
                    destory_app_sms_enter_param(p_enter_param);
                    }
                else if (p_screen_param->enter_param.type == news_type_call) {

                    void *          p_enter_param;

                    p_enter_param       = (void *) create_app_calllog_enter_param_fisrt_dial_win(3);
                    alv_am_app_exit_action(NULL,"calllog",NULL);
                    alv_am_app_enter_action(NULL,"calllog",p_enter_param);
                    destory_app_calllog_enter_param(p_enter_param);
                    }

                alv_am_app_exit_action(NULL,"remind",NULL);
                }
            break;

        case APP_KEY_VALUE_TOP_RIGHT:
            {
                if (p_screen_param->enter_param.type == news_type_sms) {
                    if (remind_fp_get_call_count()) {
                        uint8_t         str[30];

                        p_screen_param->enter_param.type = news_type_call;
                        sprintf(str,"%d个未接电话",p_screen_param->enter_param.count);
                        lv_label_set_text(p_screen_param->obj_label_remind,str);
                        break;
                        }
                    }
                else if (p_screen_param->enter_param.type == news_type_call) {
                    if (remind_fp_get_sms_count()) {
                        uint8_t         str[30];

                        sprintf(str,"%d条新消息",p_screen_param->enter_param.count);
                        p_screen_param->enter_param.type = news_type_sms;
                        lv_label_set_text(p_screen_param->obj_label_remind,str);
                        break;
                        }

                    }

                remind_fp_win_exit_current_ui();
                }
            break;

        case LV_KEY_ENTER:
            {

                }
            break;

        case LV_KEY_END:
            alv_am_app_exit_action_all();
            break;
        }
}










